    rorTitle: 'Калькулятор риска разорения',
    rorIntro: 'Моделирует 2 000 сценариев с вашим винрейтом, соотношением прибыль/риск и риском на сделку, показывая реальную вероятность тяжёлой просадки. Двигайте ползунки и смотрите, как риск на сделку меняет всё.',
    rorWinRate: 'Винрейт',
    rorRRatio: 'Прибыль/риск',
