    expandingPatternsTitle: 'Продвинутые расширяющиеся паттерны (Broadening)',
    expandingPatternsIntro: 'В отличие от классических треугольников, которые сужаются, эти паттерны РАСШИРЯЮТСЯ: линии тренда расходятся, образуя более высокие максимумы и более низкие минимумы. Отражают неопределённость и растущую волатильность. Стратегия использует 2 входа (E1 = первый прорыв, E2 = подтверждённый ретест) с двойным take profit (T1 = высота паттерна, T2 = расширенная проекция).',
    expandingPatternsTradePlan: 'Торговый план',
