    testimonial2Quote_l020: 'Strategy Optimizer и AI Coach экономят мне часы анализа. Я окупаю подписку каждый месяц всего одной грамотно спланированной сделкой.',
    testimonial2Author_l021: 'Ana R.',
    testimonial2Role_l022: 'Swing Trader по опционам',
    testimonial3Quote_l030: 'Пользуюсь ежедневно уже 8 месяцев. Monte Carlo и журнал полностью изменили моё понимание риска. 5 звёзд.',
    testimonial3Author_l031: 'David L.',
    testimonial3Role_l032: 'Независимый трейдер · Forex',
    faqQ1_l040: 'Нужно ли быть экспертом для использования?',
    faqA1_l041: 'Нет. Приложение пошагово сопровождает работу с каждым калькулятором, а Education Center охватывает всё — от основ (что такое Stop Loss) до продвинутых стратегий с опционами. Есть бесплатный Demo Trader для безрисковых тестов.',
    faqQ2_l050: 'Могу ли я отменить подписку в любой момент?',
    faqA2_l051: 'Да. Отменяйте в 1 клик из профиля. Нет обязательств. При покупке Lifetime доступ постоянный — без повторяющихся платежей.',
    faqQ3_l060: 'Какие активы поддерживаются?',
    faqA3_l061: 'Криптовалюты, Forex (28 пар), акции США (NYSE/NASDAQ), индексы (SPX, NDX, DAX и др.), сырьевые товары и фьючерсы. Данные в реальном времени через Yahoo Finance.',
    faqQ4_l070: 'ИИ Trade Coach оплачивается отдельно?',
    faqA4_l071: 'Нет. AI Trade Coach (Claude Sonnet 4.5) включён во все Premium-планы. Анализирует вашу стратегию, выявляет риски и предлагает улучшения как опытный наставник.',
    faqQ5_l080: 'Работает ли на мобильных?',
    faqA5_l081: 'Да. Полностью адаптивный дизайн. Калькуляторы и дашборд отлично работают на iOS/Android. Нативное приложение в дорожной карте на Q2.',
